select `pd`.`design_name` AS `category`,`pr`.`product_name` AS `product`,`ki`.`met_issue_date` AS `trans_date`,`iss`.`ref_no` AS `referenceno`,2 AS `trans_type`,`iitm`.`issue_met_parent_id` AS `trans_id`,if((`cat`.`cat_type` = 2),0,if((ifnull(`uom`.`divided_by_value`,0) = 0),`iitm`.`issue_metal_wt`,round((`iitm`.`issue_metal_wt` / `uom`.`divided_by_value`),3))) AS `gross_wt`,if((`cat`.`cat_type` = 2),0,if((ifnull(`uom`.`divided_by_value`,0) = 0),`iitm`.`issue_metal_wt`,round((`iitm`.`issue_metal_wt` / `uom`.`divided_by_value`),3))) AS `net_wt`,ifnull(`iitm`.`issue_pcs`,1) AS `no_of_pcs`,'100' AS `purchase_touch`,if((`pr`.`stone_type` = 0),`iitm`.`issue_metal_pur_wt`,if((ifnull(`uom`.`divided_by_value`,0) = 0),`iitm`.`issue_metal_wt`,round((`iitm`.`issue_metal_wt` / `uom`.`divided_by_value`),3))) AS `purewt`,`iss`.`id_karigar` AS `customer_id`,1 AS `trans_rec_type`,0 AS `trans_amount`,`iitm`.`issue_cat_id` AS `catid`,`pr`.`stone_type` AS `stone_type`,`iitm`.`issu_met_pro_id` AS `proid`,2 AS `trans_screen_id`,`met`.`id_metal` AS `id_metal`,`met`.`metal` AS `metal`,'' AS `rate`,'' AS `narration`,unix_timestamp(`ki`.`met_issue_date`) AS `unixtransdate`,`uom`.`uom_short_code` AS `dispuom` from ((((((((`ret_karigar_metal_issue_details` `iitm` left join `ret_karigar_metal_issue` `ki` on((`ki`.`met_issue_id` = `iitm`.`issue_met_parent_id`))) left join `smith_company_op_balance` `iss` on((`iss`.`id_smith_company_op_balance` = `iitm`.`id_smith_company_op_balance`))) left join `ret_karigar` `kr` on((`kr`.`id_karigar` = `iss`.`id_karigar`))) left join `ret_category` `cat` on((`cat`.`id_ret_category` = `iitm`.`issue_cat_id`))) left join `metal` `met` on((`met`.`id_metal` = `cat`.`id_metal`))) left join `ret_product_master` `pr` on((`pr`.`pro_id` = `iitm`.`issu_met_pro_id`))) left join `ret_design_master` `pd` on((`pd`.`design_no` = `iitm`.`issu_met_id_design`))) left join `ret_uom` `uom` on((`uom`.`uom_id` = `iitm`.`issue_uom_id`)))
WHERE ((`iitm`.`id_smith_company_op_balance` is not null) and (`ki`.`bill_status` = 1))
GROUP BY `iitm`.`issue_cat_id`,`iitm`.`issu_met_pro_id`,`iitm`.`issue_met_id`
ORDER BY `unixtransdate`;
